-- =============================================
-- fico-db 报表「数据元素」种子数据 (DML) —— 由 gen_fico_cr_element_seed.py 生成，勿手改
--   cr_element_category 7 大类 · cr_data_element 若干元素
-- 数据元素 = 报表单元格取数的最小语义单位（对标科目/指标）。设计器左侧「数据元素」面板读此二表。
-- 幂等：按本脚本 code 精确清理再插入，可重复执行。
-- 依赖：cr_element_category / cr_data_element 已由报表数据字典元数据部署到 fico-db。
-- =============================================

-- 元素大类 cr_element_category
DELETE FROM cr_element_category WHERE code IN ('balance','income','cashflow','production','sales','cost','tax');

-- 数据元素 cr_data_element（按大类分组，code = {前缀}_{NN}）
DELETE FROM cr_data_element WHERE code ~ '^(BS|PL|CF|PD|SL|CO|TX)_[0-9]{2}$';

-- 合计：7 大类 · 105 个数据元素
